// v32（我的补充）：安全规则——只收低压直流设备（≤ 24 V），市电设备不收。搜到市电类关键词时页面给出提示
export const MAX_VOLTS = 24;
export const MAINS_RX = /市电|220\s*v|110\s*v|230\s*v|交流|插座|充电头|充电器|适配器|电源适配|开关电源|家电|电饭|微波|吹风|mains|\bac\b|wall (plug|charger)|charger plug|power (adapter|supply)|adapter|appliance/i;
export const isMainsQuery = (q) => MAINS_RX.test(String(q || ""));
export const DEVICE_BY_ID = Object.fromEntries(DEVICES.map((d) => [d.id, d]));
export function searchDevices(q) {
  const s = String(q || "").trim().toLowerCase();
  if (!s) return DEVICES;
  return DEVICES.filter((d) => [d.name.zh, d.name.en, d.model, ...d.alias].some((x) => x.toLowerCase().includes(s)));
}
